/**
 * Katalog teks dasbor.
 *
 * Bahasa Indonesia adalah sumber kebenarannya: [MessageKey] diturunkan darinya,
 * sehingga kunci yang salah ketik gagal saat `tsc` dan bahasa yang kehilangan
 * kunci gagal di uji (`messages.test.ts`), bukan muncul sebagai teks aneh di
 * layar pengguna.
 *
 * Argumen ditulis `{nama}`. Penanda bernama, bukan posisi, karena urutan kata
 * berbeda antar bahasa.
 *
 * Prioritas isian: kosakata yang BERULANG di banyak halaman didahulukan —
 * tindakan, status, judul kolom tabel. Satu kunci "Batal" menutup dua puluh satu
 * tempat sekaligus, sementara satu kalimat khusus di satu halaman menutup satu.
 */

