  pfLevelMultiOutlet: 'Multi-Outlet Control',
  pfLevelMultiOutletDesc: 'Watch every branch from one account · Compare outlet performance · Separate stock and reports',
  pfSetup1: 'Sign Up and Log In to the Dashboard',
  pfSetup1Desc: 'The owner registers with an email and password, then sets the business name and type (food, retail, or services).',
  pfSetup2Desc: 'Create at least one outlet (a shop location). Each outlet has its own stock and data.',
  pfSetup3: 'Add Staff and Set Roles',
  pfSetup3Desc: 'Create staff accounts (cashier, cook, warehouse). Setting a role automatically hides the features they do not need.',
  pfSetup4: 'Enter Products and Stock',
  pfSetup4Desc: 'Add products, variants, prices, categories, and discounts. The stock appears in the register app automatically.',
  pfSetup5: 'Bind a Terminal in the Register App',
  pfSetup5Desc: 'The owner signs in on the register tablet or phone → picks an outlet → picks a terminal → the system is bound to that device.',
  pfSetup6: 'Cashier Signs In with a PIN and Opens a Shift',
  pfSetup6Desc: 'Each day the cashier signs in with a 4-digit PIN → enters the opening cash → the shift opens → ready to sell.',
  pfDaily1: 'Daily PIN Login',
  pfDaily1Desc: 'The cashier enters a 4-digit PIN. If no shift is open, they are asked to open one and enter the opening cash.',
  pfDaily2: 'Process the Order',
  pfDaily2Desc: 'Pick products → add them to the cart → choose the order type (dine-in, takeaway, or delivery).',
  pfDaily3: 'Payment and Receipt',
  pfDaily3Desc: 'Choose a payment method → enter the amount → the receipt prints automatically. Stock drops in real time.',
  pfDaily4: 'Lock the Register (Shift Handover)',
  pfDaily4Desc: 'Tap "Lock Register" → the PIN screen appears. The next cashier signs in with their PIN; no setup needed.',
  pfDaily5: 'Close the Shift',
  pfDaily5Desc: 'At the end of the shift: close it → count the closing cash → the shift report is saved and visible in the dashboard.',
  pfDaily6: 'Watch the Reports on the Web',
  pfDaily6Desc: 'The owner opens the dashboard → sees financial reports per shift → trend analytics — without being at the shop.',
  pfFaq1Q: 'What is the difference between the register app and the dashboard?',
  pfFaq2Q: 'Do cashiers have to log in again every day?',
  pfFaq2A: 'No. The device stays bound to its terminal. A cashier only enters their 4-digit PIN to start a session. Each staff member has their own PIN, so the owner is not involved in daily operations at all.',
  pfFaq3Q: 'What is a "terminal", and why does it need binding?',
  pfFaq3A: 'A terminal is the identity of a register device (a tablet or phone). Binding links the physical device to one terminal in the system, so shift, stock, and receipt data belong to the right location. One device equals one terminal.',
  pfFaq4Q: 'What if two cashiers take turns on one device?',
  pfFaq4A: 'Use "Lock Register" — the screen returns to the PIN pad. The next cashier signs in with their own PIN and a new shift opens automatically. Each cashier\'s data stays separate, session by session.',
  pfFaq5Q: 'Can stock be managed per outlet?',
  pfFaq5A: 'Yes. Each outlet has its own stock, which drops automatically with every sale there. To move stock between outlets, use Stock Transfer in the Inventory menu.',
  pfFaq6Q: 'Who can access the dashboard?',
  pfFaq6A: 'Owners and managers can reach every feature, including financial reports and permissions. Cashiers, cooks, and warehouse staff sign in through the app instead. A cashier granted web access can only see the dashboard and transactions.',
  pfFaq7Q: 'Can one account run several outlets?',
  pfFaq7A: 'Yes. One owner account can manage many outlets. The dashboard has an outlet filter — show one outlet\'s data, or all of them at once. Each outlet has its own terminals, stock, and shifts.',
  pfFaq8Q: 'What happens if the internet drops mid-sale?',
  pfFaq8A: 'The register app keeps session data locally, so completed sales are not lost. Once the connection returns, the data syncs to the server and the dashboard reports update automatically.',
