  pfWebFeatStaff: 'Pengurusan Pekerja & Kehadiran',
  pfWebFeatStaffDesc: 'Tambah pekerja, tetapkan peranan mereka, dan semak sejarah masuk dan balik daripada kiosk kaunter',
  pfWebFeatRbac: 'Kebenaran (RBAC)',
  pfWebFeatRbacDesc: 'Peranan terperinci: juruwang hanya menjual, pekerja gudang hanya stok, tukang masak hanya KDS, pengurus membaca laporan',
  pfWebFeatMultiOutlet: 'Berbilang Cawangan',
  pfWebFeatMultiOutletDesc: 'Uruskan setiap cawangan daripada satu akaun — stok, laporan, dan pekerja diasingkan bagi setiap cawangan',
  pfWebFeatOutletSettings: 'Tetapan Cawangan & Resit',
  pfWebFeatOutletSettingsDesc: 'Konfigurasikan terminal, meja, kaedah bayaran, logo resit, cukai, dan nombor giliran bagi setiap cawangan',
  pfLevelInsightsDesc: '"Produk ini jarang laku" · "Pukul 7–9 paling sibuk" · "Margin turun minggu ini" — terus pada papan pemuka',
  pfLevelMultiOutlet: 'Kawalan Berbilang Cawangan',
  pfLevelMultiOutletDesc: 'Pantau setiap cawangan daripada satu akaun · Bandingkan prestasi cawangan · Stok dan laporan berasingan',
  pfSetup1: 'Daftar dan Log Masuk ke Papan Pemuka',
  pfSetup1Desc: 'Pemilik mendaftar dengan e-mel dan kata laluan, kemudian menetapkan nama dan jenis perniagaan (makanan, runcit, atau perkhidmatan).',
  pfSetup2Desc: 'Cipta sekurang-kurangnya satu cawangan (lokasi kedai). Setiap cawangan mempunyai stok dan data sendiri.',
  pfSetup3: 'Tambah Pekerja dan Tetapkan Peranan',
  pfSetup3Desc: 'Cipta akaun pekerja (juruwang, tukang masak, gudang). Menetapkan peranan akan menyembunyikan ciri yang tidak diperlukan.',
  pfSetup4: 'Masukkan Produk dan Stok',
  pfSetup4Desc: 'Tambah produk, varian, harga, kategori, dan diskaun. Stok akan muncul dalam aplikasi kaunter secara automatik.',
  pfSetup5: 'Ikat Terminal dalam Aplikasi Kaunter',
  pfSetup5Desc: 'Pemilik log masuk pada tablet atau telefon kaunter → pilih cawangan → pilih terminal → sistem terikat pada peranti itu.',
  pfSetup6: 'Juruwang Log Masuk dengan PIN dan Buka Syif',
  pfSetup6Desc: 'Setiap hari juruwang log masuk dengan PIN 4 digit → masukkan tunai awal → syif dibuka → sedia berniaga.',
  pfDaily1: 'Log Masuk PIN Harian',
  pfDaily1Desc: 'Juruwang memasukkan PIN 4 digit. Jika tiada syif dibuka, mereka diminta membukanya dan memasukkan tunai awal.',
  pfDaily2: 'Proses Pesanan',
  pfDaily2Desc: 'Pilih produk → tambah ke troli → pilih jenis pesanan (makan di sini, bungkus, atau penghantaran).',
  pfDaily3: 'Bayaran dan Resit',
  pfDaily3Desc: 'Pilih kaedah bayaran → masukkan jumlah → resit dicetak automatik. Stok berkurang secara masa nyata.',
  pfDaily4: 'Kunci Kaunter (Tukar Syif)',
  pfDaily4Desc: 'Ketik "Kunci Kaunter" → skrin PIN muncul. Juruwang seterusnya log masuk dengan PIN mereka; tiada persediaan diperlukan.',
  pfDaily5: 'Tutup Syif',
  pfDaily5Desc: 'Pada penghujung syif: tutup syif → kira tunai akhir → laporan syif disimpan dan boleh dilihat dalam papan pemuka.',
  pfDaily6: 'Pantau Laporan di Web',
  pfDaily6Desc: 'Pemilik membuka papan pemuka → melihat laporan kewangan bagi setiap syif → analitik aliran — tanpa perlu berada di kedai.',
  pfFaq1Q: 'Apakah perbezaan antara aplikasi kaunter dan papan pemuka?',
  pfFaq2Q: 'Adakah juruwang perlu log masuk semula setiap hari?',
  pfFaq2A: 'Tidak. Peranti kekal terikat pada terminalnya. Juruwang hanya memasukkan PIN 4 digit untuk memulakan sesi. Setiap pekerja mempunyai PIN sendiri, jadi pemilik tidak perlu terlibat dalam operasi harian.',
  pfFaq3Q: 'Apakah itu "terminal", dan mengapa ia perlu diikat?',
  pfFaq3A: 'Terminal ialah identiti peranti kaunter (tablet atau telefon). Pengikatan menghubungkan peranti fizikal dengan satu terminal dalam sistem, supaya data syif, stok, dan resit tergolong pada lokasi yang betul. Satu peranti sama dengan satu terminal.',
  pfFaq4Q: 'Bagaimana jika dua juruwang bergilir pada satu peranti?',
  pfFaq4A: 'Gunakan "Kunci Kaunter" — skrin kembali ke papan PIN. Juruwang seterusnya log masuk dengan PIN sendiri dan syif baharu dibuka automatik. Data setiap juruwang kekal berasingan, sesi demi sesi.',
  pfFaq5Q: 'Bolehkah stok diurus bagi setiap cawangan?',
  pfFaq5A: 'Ya. Setiap cawangan mempunyai stok sendiri, yang berkurang automatik dengan setiap jualan di sana. Untuk memindahkan stok antara cawangan, gunakan Pemindahan Stok dalam menu Inventori.',
  pfFaq6Q: 'Siapa yang boleh mengakses papan pemuka?',
  pfFaq6A: 'Pemilik dan pengurus boleh mencapai setiap ciri, termasuk laporan kewangan dan kebenaran. Juruwang, tukang masak, dan pekerja gudang log masuk melalui aplikasi. Juruwang yang diberi akses web hanya boleh melihat papan pemuka dan transaksi.',
  pfFaq7Q: 'Bolehkah satu akaun menguruskan beberapa cawangan?',
  pfFaq7A: 'Ya. Satu akaun pemilik boleh mengurus banyak cawangan. Papan pemuka mempunyai penapis cawangan — papar data satu cawangan, atau kesemuanya sekali gus. Setiap cawangan mempunyai terminal, stok, dan syif sendiri.',
  pfFaq8Q: 'Apa yang berlaku jika internet terputus semasa jualan?',
  pfFaq8A: 'Aplikasi kaunter menyimpan data sesi secara setempat, jadi jualan yang selesai tidak hilang. Setelah sambungan pulih, data disegerakkan ke pelayan dan laporan papan pemuka dikemas kini automatik.',
