  pfDaily4Desc: '「レジをロック」をタップするとPIN画面に戻ります。次のレジ担当は自分のPINでログインするだけです。',
  pfDaily5: 'シフトを締める',
  pfDaily5Desc: 'シフト終了時：シフトを締める →締め時現金を数える →シフトレポートが保存され、管理画面で確認できます。',
  pfDaily6: 'Webでレポートを確認',
  pfDaily6Desc: 'オーナーは管理画面から、シフトごとの財務レポートや推移の分析を確認できます。お店にいる必要はありません。',
  pfFaq1Q: 'レジアプリと管理画面の違いは何ですか？',
  pfFaq2Q: 'レジ担当は毎日ログインし直す必要がありますか？',
  pfFaq2A: 'いいえ。端末はターミナルに紐づいたままです。レジ担当は4桁のPINを入力するだけでセッションを開始できます。PINは従業員ごとに異なるため、日々の運用にオーナーが関わる必要はありません。',
  pfFaq3Q: '「ターミナル」とは何ですか？なぜ紐づけが必要ですか？',
  pfFaq3A: 'ターミナルとは、レジ端末（タブレットやスマートフォン）の識別情報です。紐づけによって実機とシステム上のターミナルが結びつき、シフト・在庫・レシートのデータが正しい店舗に記録されます。1端末＝1ターミナルです。',
  pfFaq4Q: '1台の端末を2人のレジ担当が交代で使う場合はどうなりますか？',
  pfFaq4A: '「レジをロック」を使うと、画面がPIN入力に戻ります。次のレジ担当が自分のPINでログインすると、新しいシフトが自動で始まります。担当ごとのデータはセッション単位で分かれます。',
  pfFaq5Q: '在庫は店舗ごとに管理できますか？',
  pfFaq5A: 'はい。店舗ごとに在庫があり、その店舗での会計に応じて自動的に減ります。店舗間で在庫を移すには、在庫メニューの「在庫移動」をお使いください。',
  pfFaq6Q: '管理画面には誰がアクセスできますか？',
  pfFaq6A: 'オーナーと店長は、財務レポートや権限設定を含むすべての機能を利用できます。レジ担当・調理担当・倉庫担当はアプリからログインします。Webアクセスを与えられたレジ担当は、ダッシュボードと取引のみ閲覧できます。',
  pfFaq7Q: '1つのアカウントで複数店舗を運営できますか？',
  pfFaq7A: 'はい。1つのオーナーアカウントで複数の店舗を管理できます。管理画面には店舗フィルターがあり、特定の店舗だけ、または全店舗をまとめて表示できます。店舗ごとに端末・在庫・シフトが分かれます。',
  pfFaq8Q: '会計中にインターネットが切れたらどうなりますか？',
  pfFaq8A: 'レジアプリはセッションのデータを端末に保存するため、完了した会計は失われません。接続が戻るとサーバーへ同期され、管理画面のレポートも自動で更新されます。',
